import{_ as a,o as t,c as i,ah as n}from"./chunks/framework.ojwJKwrc.js";const u=JSON.parse('{"title":"Reactive SSA lowering","description":"","frontmatter":{},"headers":[],"relativePath":"internals/reactive-ssa-lowering.md","filePath":"internals/reactive-ssa-lowering.md"}'),o={name:"internals/reactive-ssa-lowering.md"};function s(r,e,l,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="reactive-ssa-lowering" tabindex="-1">Reactive SSA lowering <a class="header-anchor" href="#reactive-ssa-lowering" aria-label="Permalink to &quot;Reactive SSA lowering&quot;">​</a></h1><blockquote><p><strong>Status:</strong> architecture proposal and migration contract with the first production sink-local rewrite enabled. The current native backend still composes the combinational and FF SIR CFGs sequentially; the admitted two-state static subset removes individually proved Store/Load round trips without claiming that the full projection architecture is complete.</p></blockquote><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>The native clock-event fast path currently constructs:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>all combinational execution units</span></span>
<span class="line"><span>  -&gt; publish combinational values through Stable Stores</span></span>
<span class="line"><span>  -&gt; load those values in eval_apply_ff</span></span>
<span class="line"><span>  -&gt; compute and stage next FF values</span></span>
<span class="line"><span>  -&gt; publish FF state</span></span></code></pre></div><p>The optimizer then tries to recover value flow from the Store/Load pairs, delete publications which are not observed, sink selected producer cones, and repair the resulting live ranges during allocation.</p><p>This order is backwards for code generation. Memory publication is part of a simulator interface, but it is not the natural representation of an HDL value inside one clock event. Once publication has become ordinary SIR Store/Load instructions, later passes must rediscover:</p><ul><li>which Store and Load name the same logical range and phase version;</li><li>whether an external observer can see the publication;</li><li>which control path produced the value;</li><li>whether carrying the value or rebuilding it at a sink is cheaper; and</li><li>where the value should become physical memory rather than SSA.</li></ul><p>The July 25, 2026 fixed release/LTO gate makes the remaining scale concrete:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                         compile       execute</span></span>
<span class="line"><span>Veryl synchronous AOT-C  58.020 s      53.820 s</span></span>
<span class="line"><span>Celox native             54.407 s      59.616 s</span></span></code></pre></div><p>Both runners completed at exactly <code>cy=9ae070 x3=aa pass=1</code>. Celox therefore has a generated-execution deficit of 5.796 seconds, or 10.77%, while compiling faster. Freeing the state-base register reduced pressure but did not remove this residual architecture cost.</p><p>The failed profitability gate in <a href="./fused-state-ssa-placement.html">Fused state SSA and code placement</a> also shows that bypassing only FF-suffix packed reloads is too narrow. This document does not authorize that old Milestone 2. It replaces the unit of construction.</p><h2 id="performance-properties-of-the-desired-binary" tabindex="-1">Performance properties of the desired binary <a class="header-anchor" href="#performance-properties-of-the-desired-binary" aria-label="Permalink to &quot;Performance properties of the desired binary&quot;">​</a></h2><p>The target is not merely fewer SIR instructions. A fast generated event function should have all of these properties:</p><ol><li>Values which remain internal to one event are SSA values, not public simulation-state round trips.</li><li>Only semantic event effects, externally observable publications, and phase barriers become Stores.</li><li>A value is computed under the control condition which needs it. Case arms which are not selected do not execute their payloads.</li><li>Independent logical values use native scalar widths while in registers. Packed layout is paid for only at an admitted physical boundary.</li><li>Producer and sink are close enough that register allocation sees short ranges. Shared source syntax does not force one machine live range.</li><li>Loop-carried values and simultaneous FF sampling remain explicit; neither code placement nor rematerialization may cross a phase version.</li><li>Code size stays bounded. Duplicating a small sink-local suffix is allowed; cloning a large shared decoder or whole combinational graph is not.</li><li>The scheduler receives a dependency-ready local packet. It is not asked to recover global HDL placement from one giant, already linearized function.</li></ol><p>These are properties of the machine program. Store counts, VReg counts, and SIR size are diagnostics only.</p><p>An <code>ExecutionUnit</code> is only a physical code-generation container. In particular, putting all acyclic combinational logic in one EU must not collapse the semantic units inside it. The lowering pipeline preserves this hierarchy:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>comb process</span></span>
<span class="line"><span>  -&gt; exact LogicPath/range definitions</span></span>
<span class="line"><span>  -&gt; scheduler SCC and effect interval</span></span>
<span class="line"><span>  -&gt; SIR definition sites</span></span>
<span class="line"><span>  -&gt; MemorySSA StateVersions</span></span>
<span class="line"><span>  -&gt; FF demand cluster</span></span></code></pre></div><p>The clock projection and placement planner operate on the lower levels of this hierarchy, never on the whole comb EU as one scheduling or allocation region. Several independent FF demand clusters may refer to definitions contained in the same comb EU without acquiring a shared live range or a common materialization decision.</p><p>Semantic-region identity is retained for every elaborated comb process and for otherwise ungrouped continuous/glue LogicPaths. It is a clustering and placement hint, not a correctness proof. Optimizer-created aggregate or repartitioned Stores may not have one unique source region; their legality is still decided solely by exact MemorySSA versions and effects.</p><h2 id="the-incorrect-boundary" tabindex="-1">The incorrect boundary <a class="header-anchor" href="#the-incorrect-boundary" aria-label="Permalink to &quot;The incorrect boundary&quot;">​</a></h2><p>The parser is not required to emit machine order, and the machine backend must not parse HDL syntax again. The missing layer is between those two extremes.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Veryl/analyzer</span></span>
<span class="line"><span>  -&gt; typed process CFG and effects</span></span>
<span class="line"><span>  -&gt; Reactive SSA</span></span>
<span class="line"><span>  -&gt; root-specific event projection</span></span>
<span class="line"><span>  -&gt; machine CFG and sink packets</span></span>
<span class="line"><span>  -&gt; MIR, allocation, x86</span></span></code></pre></div><p>A parser expression DAG is insufficient because procedural priority, partial writes, dynamic indices, loops, hierarchy, runtime observations, and simultaneous FF sampling are control and state-version properties. Conversely, ordinary SIR with every interface Store already materialized is too late.</p><p>Reactive SSA is therefore a typed process CFG with explicit state versions and effects. It can initially be derived from verified SIR; the parser does not need to be rewritten before the model is validated.</p><h2 id="reactive-ssa" tabindex="-1">Reactive SSA <a class="header-anchor" href="#reactive-ssa" aria-label="Permalink to &quot;Reactive SSA&quot;">​</a></h2><h3 id="value-nodes" tabindex="-1">Value nodes <a class="header-anchor" href="#value-nodes" aria-label="Permalink to &quot;Value nodes&quot;">​</a></h3><p>A value node has:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ValueId</span></span>
<span class="line"><span>RegisterType</span></span>
<span class="line"><span>definition control region</span></span>
<span class="line"><span>operands</span></span>
<span class="line"><span>purity/effect class</span></span>
<span class="line"><span>source identity for diagnostics</span></span></code></pre></div><p>Values wider than a machine word may have a legal chunk representation, but logical widths are not VReg widths. A 27-bit HDL value remains a typed 27-bit value here and is lowered to one 32- or 64-bit machine value plus the required normalization contract.</p><h3 id="state-objects-and-versions" tabindex="-1">State objects and versions <a class="header-anchor" href="#state-objects-and-versions" aria-label="Permalink to &quot;State objects and versions&quot;">​</a></h3><p>A state access names:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>StateObject</span></span>
<span class="line"><span>exact bit range or typed element range</span></span>
<span class="line"><span>phase</span></span>
<span class="line"><span>StateVersion</span></span>
<span class="line"><span>value/mask plane</span></span></code></pre></div><p>The initial phases are:</p><ul><li><code>PersistentInput</code>: state visible at event entry;</li><li><code>CombDerived</code>: a value produced while evaluating combinational logic;</li><li><code>NextFF</code>: a staged next-state value not yet visible to ordinary FF reads;</li><li><code>PublishedFF</code>: the version made visible by the event commit barrier.</li></ul><p>A <code>StatePhi</code> represents path or loop merging. It is not an ambiguous set of reaching definitions. Partial writes construct a new range version from the previous version and inserted bits.</p><h3 id="effects" tabindex="-1">Effects <a class="header-anchor" href="#effects" aria-label="Permalink to &quot;Effects&quot;">​</a></h3><p>Effects are explicit nodes ordered by an effect token:</p><ul><li>runtime error/assert/display/capture;</li><li>trigger publication;</li><li>dynamic or unresolved memory access;</li><li>externally required combinational publication;</li><li><code>StageNextFF</code>;</li><li><code>CommitFFState</code>.</li></ul><p><code>StageNextFF</code> has an earliest point after its value, guard, and state dependencies and a latest point before <code>CommitFFState</code>. The commit is a fixed phase barrier which publishes the final version of every staged FF range.</p><h3 id="materialization-sources" tabindex="-1">Materialization sources <a class="header-anchor" href="#materialization-sources" aria-label="Permalink to &quot;Materialization sources&quot;">​</a></h3><p>A state or value edge may end at an executable materialization source:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Constant</span></span>
<span class="line"><span>DominatingSSA</span></span>
<span class="line"><span>ReadPersistentState</span></span>
<span class="line"><span>ReloadPreservedHome</span></span>
<span class="line"><span>ControlMerge</span></span></code></pre></div><p>Naming a StateVersion is not enough. Every source states how the value is obtained at its use cluster and proves dominance, phase equality, range identity, and control legality.</p><h2 id="root-specific-projections" tabindex="-1">Root-specific projections <a class="header-anchor" href="#root-specific-projections" aria-label="Permalink to &quot;Root-specific projections&quot;">​</a></h2><p>One elaborated Reactive SSA graph produces multiple executable projections.</p><h3 id="combinational-projection" tabindex="-1">Combinational projection <a class="header-anchor" href="#combinational-projection" aria-label="Permalink to &quot;Combinational projection&quot;">​</a></h3><p>Roots are:</p><ul><li>public combinational outputs required by the simulator interface;</li><li>triggers, captures, observations, and runtime effects;</li><li>convergence/SCC effects.</li></ul><p>This projection preserves the current generic <code>eval_comb</code> contract.</p><h3 id="clock-event-projection" tabindex="-1">Clock-event projection <a class="header-anchor" href="#clock-event-projection" aria-label="Permalink to &quot;Clock-event projection&quot;">​</a></h3><p>Roots are:</p><ul><li>FF next-state values for the selected clock/reset domain;</li><li><code>StageNextFF</code> and <code>CommitFFState</code>;</li><li>event-local observations and runtime effects;</li><li>comb publications which are independently proved observable before the simulator marks combinational state dirty.</li></ul><p>An ordinary comb Store is not inherited from the combinational projection. If a comb-derived value feeds only an FF next-state expression, the clock projection contains a value edge, not a Store followed by a Load.</p><h3 id="split-evaluate-apply-projection" tabindex="-1">Split evaluate/apply projection <a class="header-anchor" href="#split-evaluate-apply-projection" aria-label="Permalink to &quot;Split evaluate/apply projection&quot;">​</a></h3><p>Cascade and simultaneous-domain execution still require:</p><ul><li>an evaluate projection which stages <code>NextFF</code> without publication; and</li><li>an apply projection containing only the publication barrier and required trigger effects.</li></ul><p>The single-domain fused projection is an optimization of the same phase graph, not a separately parsed semantic program.</p><h2 id="projection-construction" tabindex="-1">Projection construction <a class="header-anchor" href="#projection-construction" aria-label="Permalink to &quot;Projection construction&quot;">​</a></h2><p>For one requested projection:</p><ol><li>Select semantic effect roots and requested state publications.</li><li>Walk backward through exact SSA and StateSSA def-use edges.</li><li>Retain required control dependence and loop-carried SCC edges.</li><li>Stop at executable materialization sources.</li><li>Partition uses into sink clusters by control region, loop context, and effect interval.</li><li>Choose for each cluster: <ul><li>carry a dominating value;</li><li>rematerialize a bounded pure suffix;</li><li>reload an exact preserved home; or</li><li>retain the original packed path.</li></ul></li><li>Construct machine CFG only for the retained projection.</li><li>Emit bounded sink packets to machine scheduling and allocation.</li></ol><p>This is sparse graph reachability. It does not enumerate paths and does not construct a whole-function scheduling DAG.</p><p>The first implementation represents every FF state Load as an independent MemorySSA demand root. Its reaching <code>Def</code>, <code>MemoryPhi</code>, or <code>LiveOnEntry</code> version is expanded without treating a merge as ambiguous. A silent comb publication <code>Def</code> crosses into the defining SSA value; an observable publication remains an effect frontier. This establishes clusters before any Store deletion or code motion is attempted.</p><p>On the Heliodor Linux workload, the first demand-cluster trace reports:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FF state demand clusters       3,704</span></span>
<span class="line"><span>complete clusters              3,242</span></span>
<span class="line"><span>comb-publication-backed        2,017</span></span>
<span class="line"><span>pure suffix instructions      41,821</span></span>
<span class="line"><span>largest pure suffix              579</span></span>
<span class="line"><span>SIR control merges             1,880</span></span>
<span class="line"><span>unsupported frontiers            462</span></span></code></pre></div><p>After connecting source semantic regions to MemorySSA definitions, 1,824 of the 2,017 publication-backed clusters have an unambiguous region identity. The remaining 193 include definitions whose optimized range no longer has one unique containing source range. They remain valid MemorySSA clusters and must not be rejected or guessed solely from provenance.</p><p>Point-specific MemorySSA checks of producer-cone Load frontiers report 17,030 state Load leaves. Of these, 15,582 (91.5%) observe exactly the same StateVersion at the target FF use cluster and may be reloaded there. The remaining 1,448 must retain an earlier value or stop at a version-valid frontier; moving them unconditionally would change RTL semantics. Queries use a sorted per-block/per-slot definition index rather than rescanning all MemorySSA accesses per leaf.</p><p>The whole retained projection still contains 13,040 instructions and exceeds the obsolete 4,096-instruction whole-projection limit. No individual demand cluster does. This is evidence for sink-local construction, not yet a runtime speedup: shared producer accounting, cluster partitioning, and executable control placement are still required before code generation.</p><h2 id="placement-and-allocation" tabindex="-1">Placement and allocation <a class="header-anchor" href="#placement-and-allocation" aria-label="Permalink to &quot;Placement and allocation&quot;">​</a></h2><p>Global placement and machine scheduling remain distinct.</p><p>Reactive SSA chooses a legal control region and materialization source. The machine scheduler orders only the instructions in a bounded packet whose external values and effects are already explicit. Register allocation may downgrade:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DirectForward -&gt; Rematerialize -&gt; ReloadPreservedHome</span></span>
<span class="line"><span>DirectForward -&gt; ReloadPreservedHome</span></span></code></pre></div><p>It may split a use cluster but may never merge clusters or silently recreate one long shared live range. Plan-local rematerializations have stable identities so ordinary CSE cannot merge them across cluster boundaries.</p><p>The allocator remains responsible for:</p><ul><li>exact point/edge homes;</li><li>fixed-register constraints;</li><li>spill decisions;</li><li>phi-edge parallel copies; and</li><li>final physical assignment.</li></ul><p>It is not responsible for deciding which HDL case arm or combinational publication belongs in the event.</p><h2 id="complexity-and-memory-bounds" tabindex="-1">Complexity and memory bounds <a class="header-anchor" href="#complexity-and-memory-bounds" aria-label="Permalink to &quot;Complexity and memory bounds&quot;">​</a></h2><p>Let <code>V</code> be retained value/effect nodes, <code>E</code> retained SSA/control edges, <code>R</code> range endpoints, and <code>P</code> emitted machine instructions.</p><ul><li>state-range indexing: <code>O(R log R)</code> construction;</li><li>sparse StateSSA: <code>O(V + E)</code> over accessed ranges;</li><li>root projection: <code>O(V + E)</code> in the visited subgraph;</li><li>SCC discovery: <code>O(V + E)</code>;</li><li>packet construction: <code>O(P + dependency edges)</code>;</li><li>resident analysis storage: <code>O(V + E + R)</code>.</li></ul><p>The implementation must not allocate:</p><ul><li>a value-by-block matrix;</li><li>all-pairs alias or dominance tables;</li><li>one cloned graph per sink;</li><li>complete path sets; or</li><li>a second full instruction order.</li></ul><p>Temporary projection tables are dropped before MIR allocation. Stage RSS is reported separately from peak RSS.</p><h2 id="migration" tabindex="-1">Migration <a class="header-anchor" href="#migration" aria-label="Permalink to &quot;Migration&quot;">​</a></h2><h3 id="step-a-explicit-fused-phase-cut" tabindex="-1">Step A: explicit fused phase cut <a class="header-anchor" href="#step-a-explicit-fused-phase-cut" aria-label="Permalink to &quot;Step A: explicit fused phase cut&quot;">​</a></h3><p>Replace the positional <code>Option&lt;usize&gt;</code> suffix convention with a typed clock event composition. Verify:</p><ul><li>the FF entry exists;</li><li>every FF-reachable block remains inside the FF suffix;</li><li>no FF edge returns to a comb block;</li><li>the phase classification covers every merged block; and</li><li>generic chained functions do not acquire an implicit phase.</li></ul><p>This step changes no generated instructions. Its purpose is to prevent future projection code from inferring phase semantics from unit order.</p><h3 id="step-b-projection-oracle" tabindex="-1">Step B: projection oracle <a class="header-anchor" href="#step-b-projection-oracle" aria-label="Permalink to &quot;Step B: projection oracle&quot;">​</a></h3><p>Build Reactive SSA from the current merged SIR without rewriting it. Emit, for each projection:</p><ul><li>roots by effect class;</li><li>retained values, blocks, and ranges;</li><li>comb publications absent from the clock projection;</li><li>materialization frontier sources;</li><li>loop/control cutoffs; and</li><li>bounded memory/time measurements.</li></ul><p>The existing generated SIR/MIR remains the executable reference.</p><h4 id="implemented-analysis-contract" tabindex="-1">Implemented analysis contract <a class="header-anchor" href="#implemented-analysis-contract" aria-label="Permalink to &quot;Implemented analysis contract&quot;">​</a></h4><p>The first projection oracle is now built from the exact merged SIR before any merged-chain rewrite. It is captured only by an explicit native IR trace and does not add analysis time to ordinary production compilation.</p><p>The graph combines:</p><ul><li>exact source-EU and comb/FF block provenance;</li><li>SIR SSA value and block-parameter edges;</li><li>sparse StateSSA versions for stable, working, and sparse-working state;</li><li>exact cross-region Commit copies;</li><li>FF publication Commit, observable Store, runtime event, capture, and error roots; and</li><li>live-on-entry, unresolved alias, loop-control, and unsupported-access frontiers.</li></ul><p><code>Commit(stable -&gt; working)</code> is a state-copy edge, not a publication root. <code>Commit(working|sparse-working -&gt; stable)</code> is a publication root. This distinction ensures that the projection starts from final published FF versions and reaches only the staged definitions which can affect them, instead of treating every intermediate working Store as a sink.</p><p>The implementation uses one work-list visit per retained SSA instruction and control block. It does not revisit a shared producer once per root and does not construct full control-dependence or value-by-block matrices.</p><p>The native trace writes the complete report to <code>reactive_event_graph.txt</code>. For the Heliodor Linux workload at <code>7ad830fc0f8506c934b61a853ce2eadfa5926b82</code>, the clock projection completed inside the existing full trace compile and reported:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>units                       37  (1 comb, 36 FF)</span></span>
<span class="line"><span>semantic roots             719</span></span>
<span class="line"><span>retained blocks           1,131</span></span>
<span class="line"><span>retained instructions    13,040</span></span>
<span class="line"><span>materialization cutoffs   2,153</span></span>
<span class="line"><span>cross-EU state flows         45</span></span></code></pre></div><p>The 45 exact cross-EU flows connect the comb EU to FF EUs by state range and StateVersion. The cutoff set contains 1,765 live-on-entry sources, 232 real memory kills, and 156 loop-control boundaries. These are feasibility facts, not a speedup claim: Step C must still turn each admitted frontier into an executable materialization source and compare the resulting state/effects against the existing fused function.</p><h3 id="step-c-straight-line-static-clock-projection" tabindex="-1">Step C: straight-line static clock projection <a class="header-anchor" href="#step-c-straight-line-static-clock-projection" aria-label="Permalink to &quot;Step C: straight-line static clock projection&quot;">​</a></h3><p>Generate code directly for a deliberately small subset:</p><ul><li>two-state;</li><li>static non-overlapping ranges;</li><li>acyclic control region;</li><li>no capture/trigger/runtime effect between producer and FF sink;</li><li>exact persistent input or dominating SSA frontier;</li><li>bounded sink-local recipe.</li></ul><p>Compile both the old fused function and the new projection in tests. Execute randomized input states and compare final Stable/Working/triggered memory plus status.</p><p>The first production rewrite admits only a bounded, branchless SIR projection with exact static StateSSA edges and executable sink-local frontiers. For an exact comb-Store to FF-Load edge it:</p><ol><li>is disabled for four-state execution until value and mask planes can be proved and deleted atomically;</li><li>requires identical static address, range, and SIR value type;</li><li>requires an effect-free comb Store and one exact FF Load consumer;</li><li>rejects any other static or dynamic read overlapping the Store range, including differently shaped accesses which MemorySSA represents as kills;</li><li>clones at most 16 pure SSA instructions, including definitions from dominating predecessor blocks, immediately before the FF Load;</li><li>requires every state Load frontier to observe the same event StateVersion and the same physically reloadable StateVersion at the sink;</li><li>computes which original cone instructions become dead after deleting the publication and admits the rewrite only when the cloned cone is no larger than the dead cone plus the removed Store and Load;</li><li>removes the FF Load and comb Store together; and</li><li>runs ordinary SIR DCE and verification.</li></ol><p>A focused differential test executes the old fused SIR and projected SIR over several input states, then executes the ordinary comb projection before comparing state. This models the simulator&#39;s dirty-comb contract: a clock-only projection need not publish an unobserved intermediate comb value, but the value must be reconstructed before an external observation.</p><p>An additional regression preserves a 64-bit publication when a 12-bit overlapping Load also consumes it. The initial implementation checked only the 64-bit MemorySSA Def&#39;s exact consumers and deleted the whole Store, delaying the Heliodor Linux completion marker by one 10,000-cycle polling interval. Inspection of the complete generated SIR exposed the differently shaped Load; the range-wide read index above closes that hole.</p><p>The initial production subset incorrectly restricted every producer cone to the Store&#39;s basic block and therefore admitted only 114 clusters. Removing that restriction without a profitability contract admitted 285 clusters, but duplicated shared, already optimized packed-bit cones. Although memory operands decreased, the final x86 function grew by 342 instructions: <code>and +105</code>, <code>test +73</code>, <code>shr +45</code>, and <code>xchg +47</code>. Store/Load elimination had been traded for repeated extraction work and additional allocation copies.</p><p>The dead-cone contract above admits 160 clusters on the Heliodor Linux workload. Relative to the phase-cut baseline, native optimized SIR decreases from 18,811,600 to 18,784,955 bytes and MIR from 54,736,563 to 54,695,093 bytes. Relative to the old 114-cluster subset, the final x86 function has 105 fewer instructions, 101 fewer memory operands, 84 fewer GS state accesses, and 47 fewer memory-source <code>movzx</code> instructions. A non-LTO optimized qualification completed kernel power-down at the exact <code>cy=9ae070 x3=aa pass=1</code> marker, with 75.710 seconds of code generation and 62.194 seconds of generated execution. The release/LTO qualification reached the same exact marker with 67.231 seconds of code generation and 61.940 seconds of generated execution. Host timing varies by several seconds; the structural machine-code deltas and exact cycle marker are the acceptance evidence here, not either single wall-clock sample.</p><h3 id="step-d-control-pure-regions" tabindex="-1">Step D: control-pure regions <a class="header-anchor" href="#step-d-control-pure-regions" aria-label="Permalink to &quot;Step D: control-pure regions&quot;">​</a></h3><p>Add exact branch priority, <code>ControlMerge</code>, and loop-independent case regions. Do not speculate payloads. Each selected arm executes only its own recipe and rejoins one verified continuation.</p><h3 id="step-e-replace-the-fused-fast-path" tabindex="-1">Step E: replace the fused fast path <a class="header-anchor" href="#step-e-replace-the-fused-fast-path" aria-label="Permalink to &quot;Step E: replace the fused fast path&quot;">​</a></h3><p>Use the clock projection for admitted domains while retaining the old fused function as a differential oracle in tests. Generic <code>eval_comb</code>, <code>eval_only_ff</code>, and <code>apply_ff</code> remain unchanged until their corresponding projections pass independently.</p><p>Only after the complete semantic gate may the old fused concatenation path be removed.</p><h2 id="gates" tabindex="-1">Gates <a class="header-anchor" href="#gates" aria-label="Permalink to &quot;Gates&quot;">​</a></h2><p>Every code-generating step runs:</p><ul><li>focused projection and phase tests;</li><li>full <code>celox</code> library tests;</li><li>native execution and native testbench integration tests;</li><li>exact Heliodor <code>cy=9ae070 x3=aa pass=1</code>;</li><li>separated compile and execute timing; and</li><li>complete final SIR/MIR inspection.</li></ul><p>The final release/LTO gate compares generated execution, not process or compile time. A transformation is not accepted merely because it removes Stores: it must improve the identified machine work without increasing spills, code size, or unselected control work enough to lose the gain.</p><h2 id="rejected-shortcuts" tabindex="-1">Rejected shortcuts <a class="header-anchor" href="#rejected-shortcuts" aria-label="Permalink to &quot;Rejected shortcuts&quot;">​</a></h2><ul><li><strong>Inlining comb syntax into FF parsing:</strong> duplicates HDL semantic analysis and loses verified CFG/effect structure.</li><li><strong>Deleting all comb Stores in the fused function:</strong> external observations, triggers, and dynamic aliases remain real roots.</li><li><strong>Forwarding every Store to every FF Load:</strong> recreates whole-function live ranges and allocator spills.</li><li><strong>One giant expression DAG:</strong> cannot represent effect order, partial writes, loops, or simultaneous FF sampling and has unacceptable scheduling scale.</li><li><strong>Arbitrary allocation regions:</strong> partitioning after placement cannot recover the missing event projection.</li><li><strong>Function splitting as the primary fix:</strong> it can change I-cache and allocation behavior but does not remove semantic work which should never have entered the clock projection.</li></ul><h2 id="related-documents" tabindex="-1">Related documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related documents&quot;">​</a></h2><ul><li><a href="./fused-state-ssa-placement.html">Fused state SSA and code placement</a></li><li><a href="./native-throughput-execution-plan.html">Native throughput execution plan</a></li><li><a href="./native-register-allocation.html">Native register allocation</a></li><li><a href="./architecture.html">Simulator architecture</a></li></ul>`,123)])])}const m=a(o,[["render",s]]);export{u as __pageData,m as default};
